def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.full_like(bins, -np.inf, dtype=float)
    fit = (rem >= 0)
    if not np.any(fit):
        return scores
    max_cap = np.max(bins) if len(bins) > 0 else 1.0
    empty_mask = (bins == max_cap) & fit
    non_empty_fit = fit & ~empty_mask
    if np.any(non_empty_fit):
        scores[non_empty_fit] = -rem[non_empty_fit]
    if np.any(empty_mask):
        first_empty = np.argmax(empty_mask)
        scores[:] = -np.inf
        scores[first_empty] = 0.0
        if np.any(non_empty_fit):
            best_non_empty = np.argmax(np.where(non_empty_fit, scores, -np.inf))
            if np.any(non_empty_fit):
                scores[non_empty_fit] = -rem[non_empty_fit]
                if np.max(-rem[non_empty_fit]) > -max_cap * 0.5:
                    pass
                else:
                    scores[first_empty] = np.max(-rem[non_empty_fit]) - 1.0
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
